INSERT INTO email_template_types(type_key, name, description)
VALUES
 ('HOME_SELLER_WELCOME', 'Home Seller Welcome', 'Welcome email for home sellers'),
 ('BULK_SELLER_WELCOME', 'Bulk Seller Welcome', 'Welcome email for bulk sellers'),
 ('PASSWORD_RESET', 'Password Reset', 'Password reset link email'),
 ('SELLER_PICKUP_SUBMITTED', 'Seller Pickup Submitted', 'Pickup submission confirmation'),
 ('SELLER_PICKUP_STATUS_UPDATE', 'Seller Pickup Status Update', 'Pickup status update email')
ON CONFLICT (type_key) DO NOTHING;

INSERT INTO email_templates(template_type_id, template_key, name, description, version, subject, html_content, text_content, variables_json, active)
SELECT type_id, template_key, name, description, 1, subject, html_content, text_content, variables_json::jsonb, true
FROM (VALUES
 ((SELECT id FROM email_template_types WHERE type_key='HOME_SELLER_WELCOME'), 'HOME_SELLER_WELCOME', 'Home Seller Welcome', 'Welcome email for home sellers', 'Welcome to ScrapFlow, {{fullName}}!', '<h2>Welcome to ScrapFlow, {{fullName}}!</h2><p>Your Home Seller account has been created successfully.</p><p><a href="{{loginUrl}}">Login to ScrapFlow</a></p><p>Registered email: {{email}}</p><p>Thank you,<br>ScrapFlow Team</p>', 'Welcome to ScrapFlow, {{fullName}}! Your Home Seller account is ready. Login: {{loginUrl}}', '{"fullName":{"type":"string","required":true},"email":{"type":"string","required":true},"loginUrl":{"type":"string","required":true}}'),
 ((SELECT id FROM email_template_types WHERE type_key='BULK_SELLER_WELCOME'), 'BULK_SELLER_WELCOME', 'Bulk Seller Welcome', 'Welcome email for bulk sellers', 'Welcome to ScrapFlow, {{businessName}}!', '<h2>Welcome to ScrapFlow, {{fullName}}!</h2><p>Your Bulk Seller account for <strong>{{businessName}}</strong> is ready.</p><p><a href="{{loginUrl}}">Login to ScrapFlow</a></p><p>Thank you,<br>ScrapFlow Team</p>', 'Welcome to ScrapFlow, {{fullName}}! Your Bulk Seller account for {{businessName}} is ready. Login: {{loginUrl}}', '{"fullName":{"type":"string","required":true},"businessName":{"type":"string","required":true},"email":{"type":"string","required":true},"loginUrl":{"type":"string","required":true}}'),
 ((SELECT id FROM email_template_types WHERE type_key='PASSWORD_RESET'), 'PASSWORD_RESET', 'Forgot Password', 'Password reset email', 'Reset your ScrapFlow password', '<h2>Password Reset Request</h2><p>Hello {{fullName}},</p><p>Reset your password using the link below:</p><p><a href="{{resetUrl}}">Reset Password</a></p><p>This link expires in {{expiresInMinutes}} minutes.</p><p>If you did not request this, ignore this email.</p>', 'Hello {{fullName}}, reset your password here: {{resetUrl}}. This link expires in {{expiresInMinutes}} minutes.', '{"fullName":{"type":"string","required":true},"resetUrl":{"type":"string","required":true},"expiresInMinutes":{"type":"string","required":true}}'),
 ((SELECT id FROM email_template_types WHERE type_key='SELLER_PICKUP_SUBMITTED'), 'SELLER_PICKUP_SUBMITTED', 'Pickup Submitted', 'Pickup request confirmation', 'Pickup request submitted - {{pickupId}}', '<h2>Pickup Request Submitted</h2><p>Hello {{fullName}},</p><p>Your pickup request <strong>{{pickupId}}</strong> was submitted successfully.</p><p>Date: {{preferredDate}}<br>Time: {{preferredTime}}<br>Estimated amount: {{estimatedAmount}}</p>', 'Hello {{fullName}}, your pickup {{pickupId}} was submitted. Date: {{preferredDate}}, Time: {{preferredTime}}, Amount: {{estimatedAmount}}.', '{"fullName":{"type":"string","required":true},"pickupId":{"type":"string","required":true},"preferredDate":{"type":"string","required":true},"preferredTime":{"type":"string","required":false},"estimatedAmount":{"type":"string","required":false}}'),
 ((SELECT id FROM email_template_types WHERE type_key='SELLER_PICKUP_STATUS_UPDATE'), 'SELLER_PICKUP_STATUS_UPDATE', 'Pickup Status Update', 'Pickup status update', 'Pickup status updated - {{pickupId}}', '<h2>Pickup Status Updated</h2><p>Hello {{fullName}},</p><p>Pickup <strong>{{pickupId}}</strong> is now <strong>{{status}}</strong>.</p><p>{{message}}</p><p><a href="{{pickupUrl}}">View Pickup Request</a></p>', 'Hello {{fullName}}, pickup {{pickupId}} is now {{status}}. {{message}} View: {{pickupUrl}}', '{"fullName":{"type":"string","required":true},"pickupId":{"type":"string","required":true},"status":{"type":"string","required":true},"message":{"type":"string","required":false},"pickupUrl":{"type":"string","required":true}}')
) AS seed(type_id, template_key, name, description, subject, html_content, text_content, variables_json)
ON CONFLICT (template_key) DO NOTHING;
